-- 000003_recurring_schedules.sql
-- Purpose: Add a practical recurring-schedule model.
--
-- A `maintenance_schedules` row can now declare a recurrence rule
-- (`recurrence_rule` = 'monthly' | 'quarterly' | 'none') and an end date
-- (`recurrence_end`). Concrete occurrences are materialised into the
-- `maintenance_recurrences` table so the calendar grid can query them
-- efficiently without generating rows on every read.
--
-- The parent row keeps its original `date` / `scheduled_at` as the *first*
-- occurrence. Subsequent occurrences are generated by the API layer and
-- stored here. The `date` column on `maintenance_recurrences` is kept as a
-- DATE for cheap calendar-range filtering while `scheduled_at` carries the
-- full timestamp.

CREATE TABLE IF NOT EXISTS maintenance_recurrences (
  id SERIAL PRIMARY KEY,
  parent_schedule_id INTEGER NOT NULL REFERENCES maintenance_schedules(id) ON DELETE CASCADE,
  occurrence_date DATE NOT NULL,
  scheduled_at TIMESTAMPTZ NOT NULL,
  status VARCHAR(30) DEFAULT 'scheduled' CHECK (status IN ('scheduled', 'in_progress', 'completed', 'cancelled', 'overdue')),
  department VARCHAR(255),
  room VARCHAR(255),
  asset_type VARCHAR(100) CHECK (asset_type IN ('laptop', 'desktop', 'network_equipment', 'printer')),
  asset_identifier VARCHAR(255),
  description TEXT,
  technician VARCHAR(255),
  priority VARCHAR(20) DEFAULT 'medium' CHECK (priority IN ('low', 'medium', 'high', 'critical')),
  reminder_days INTEGER DEFAULT 1,
  created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Enforce recurrence_rule enum via CHECK if it does not already exist.
ALTER TABLE maintenance_schedules
  DROP CONSTRAINT IF EXISTS maintenance_schedules_recurrence_rule_check;

ALTER TABLE maintenance_schedules
  ADD CONSTRAINT maintenance_schedules_recurrence_rule_check
  CHECK (recurrence_rule IS NULL OR recurrence_rule IN ('none', 'monthly', 'quarterly'));

CREATE INDEX IF NOT EXISTS idx_recurrences_parent ON maintenance_recurrences(parent_schedule_id);
CREATE INDEX IF NOT EXISTS idx_recurrences_date ON maintenance_recurrences(occurrence_date);
CREATE INDEX IF NOT EXISTS idx_recurrences_scheduled_at ON maintenance_recurrences(scheduled_at);
CREATE INDEX IF NOT EXISTS idx_recurrences_status ON maintenance_recurrences(status);

-- updated_at trigger for the new table.
DROP TRIGGER IF EXISTS trg_maintenance_recurrences_updated_at ON maintenance_recurrences;
CREATE TRIGGER trg_maintenance_recurrences_updated_at
BEFORE UPDATE ON maintenance_recurrences
FOR EACH ROW EXECUTE FUNCTION set_updated_at();